from pathlib import Path

ROOT = Path('Afterfall')

controller = ROOT / 'src/main/java/dev/afterfall/blockentity/AirlockControllerBlockEntity.java'
text = controller.read_text()
needle = '''    public boolean requestFromController(ServerLevel level, ServerPlayer requester) {\n'''
assert needle in text, 'requestFromController anchor missing'
method = '''    /**\n     * Handles a direct click on one of the two linked airlock doors.\n     * Outside the chamber the clicked door becomes the ENTRY door. Inside the\n     * chamber the clicked door becomes the requested EXIT door. This prevents\n     * vanilla/manual door interaction from bypassing the automatic interlock.\n     */\n    public boolean requestDoorCycle(ServerLevel level, BlockPos requestedDoor, ServerPlayer requester) {\n        if (!enabled) {\n            requester.displayClientMessage(Component.literal("AIRLOCK: CONTROLLER SWITCHED OFF").withStyle(ChatFormatting.RED), true);\n            return false;\n        }\n        if (isBusy()) {\n            requester.displayClientMessage(Component.literal("AIRLOCK: BUSY - " + cycleLabel()).withStyle(ChatFormatting.YELLOW), true);\n            return false;\n        }\n        if (!hasPowerAvailable(level)) {\n            requester.displayClientMessage(Component.literal("AIRLOCK: NO POWER").withStyle(ChatFormatting.RED), true);\n            return false;\n        }\n        if (!filters.complete()) {\n            requester.displayClientMessage(Component.literal("AIRLOCK: FILTER MEDIA REQUIRED | " + filters.compactStatus()).withStyle(ChatFormatting.RED), true);\n            return false;\n        }\n\n        List<BlockPos> doors = AirlockLogic.findTwoDoors(level, worldPosition);\n        BlockPos clicked = AirlockLogic.lowerDoorPos(level, requestedDoor);\n        if (doors.size() != 2 || clicked == null || !doors.contains(clicked)) {\n            requester.displayClientMessage(Component.literal("AIRLOCK: NOT CONFIGURED - TWO LINKED DOORS REQUIRED").withStyle(ChatFormatting.RED), true);\n            return false;\n        }\n\n        // Establish the chamber with both doors physically closed. No atmosphere\n        // exchange is performed merely because the player clicked a door.\n        AirlockLogic.setDoorOpen(level, doors.get(0), false);\n        AirlockLogic.setDoorOpen(level, doors.get(1), false);\n        RoomScanResult chamber = RoomMachineUtil.findSealedAdjacentRoom(level, worldPosition);\n        if (chamber == null || chamber.volume() > AirlockLogic.MAX_AIRLOCK_VOLUME) {\n            requester.displayClientMessage(Component.literal(chamber == null\n                    ? "AIRLOCK: CHAMBER NOT SEALED"\n                    : "AIRLOCK: CHAMBER TOO LARGE").withStyle(ChatFormatting.RED), true);\n            return false;\n        }\n\n        RoomScanResult playerScan = RoomScanner.scan(level, requester.blockPosition());\n        boolean playerInside = playerScan.sealed() && playerScan.anchor().equals(chamber.anchor());\n        if (!playerInside) {\n            return requestCycle(level, clicked, requester);\n        }\n\n        BlockPos other = doors.get(0).equals(clicked) ? doors.get(1) : doors.get(0);\n        Direction exitSide = AirlockLogic.chamberSideForDoor(level, clicked, chamber.anchor());\n        Direction entrySide = AirlockLogic.chamberSideForDoor(level, other, chamber.anchor());\n        if (exitSide == null || entrySide == null) {\n            requester.displayClientMessage(Component.literal("AIRLOCK: DOOR ORIENTATION COULD NOT BE RESOLVED").withStyle(ChatFormatting.RED), true);\n            return false;\n        }\n\n        this.entryDoor = other;\n        this.exitDoor = clicked;\n        this.chamberAnchor = chamber.anchor();\n        this.entryChamberSide = entrySide;\n        this.exitChamberSide = exitSide;\n        this.requesterId = requester.getUUID();\n\n        AirlockLogic.AirlockStatus status = AirlockLogic.inspectStatus(level, worldPosition);\n        if (status.safe()) {\n            transition(level, CycleState.OPENING_EXIT,\n                    Component.literal("AIRLOCK: SAFE - OPENING SELECTED EXIT").withStyle(ChatFormatting.GREEN));\n        } else {\n            transition(level, CycleState.PURGING,\n                    Component.literal("AIRLOCK: EXIT REQUESTED - PURGING").withStyle(ChatFormatting.YELLOW));\n        }\n        return true;\n    }\n\n'''
text = text.replace(needle, method + needle, 1)
controller.write_text(text)

common = ROOT / 'src/main/java/dev/afterfall/event/CommonEvents.java'
text = common.read_text()
old = '''        if (controllerPos != null && event.getLevel() instanceof ServerLevel serverLevel) {\n            BlockEntity blockEntity = serverLevel.getBlockEntity(controllerPos);\n            if (blockEntity instanceof AirlockControllerBlockEntity controller && controller.isBusy()) {\n                event.setCancellationResult(InteractionResult.FAIL);\n                event.setCanceled(true);\n                if (event.getEntity() instanceof ServerPlayer player) {\n                    player.displayClientMessage(Component.literal("Airlock automatic cycle active: manual door control locked."), true);\n                }\n                return;\n            }\n        }\n\n        if (!state.hasProperty(BlockStateProperties.OPEN) || state.getValue(BlockStateProperties.OPEN)) return;\n\n        if (controllerPos != null && AirlockLogic.otherLinkedDoorOpen(event.getLevel(), controllerPos, event.getPos())) {\n            event.setCancellationResult(InteractionResult.FAIL);\n            event.setCanceled(true);\n            if (event.getEntity() instanceof ServerPlayer player) {\n                player.displayClientMessage(Component.literal("Airlock interlock: close the other door first."), true);\n            }\n            return;\n        }\n\n        if (event.getLevel() instanceof ServerLevel serverLevel) {\n            RoomEnvironmentManager.equilibrateAcrossClosedDoor(serverLevel, event.getPos());\n            if (event.getEntity() instanceof ServerPlayer player) {\n                RoomEnvironmentManager.invalidate(player);\n                if (controllerPos != null) {\n                    AirlockLogic.AirlockStatus status = AirlockLogic.inspectStatus(serverLevel, controllerPos);\n                    player.displayClientMessage(AirlockControllerBlockEntity.shortStatus(status), true);\n                }\n            }\n        }\n'''
new = '''        // A linked airlock door is never opened through vanilla/manual door logic.\n        // The controller owns the complete interaction so atmosphere exchange only\n        // happens when the automatic cycle actually opens a door.\n        if (controllerPos != null && event.getLevel() instanceof ServerLevel serverLevel) {\n            event.setCancellationResult(InteractionResult.SUCCESS);\n            event.setCanceled(true);\n            BlockEntity blockEntity = serverLevel.getBlockEntity(controllerPos);\n            if (event.getEntity() instanceof ServerPlayer player\n                    && blockEntity instanceof AirlockControllerBlockEntity controller) {\n                controller.requestDoorCycle(serverLevel, event.getPos(), player);\n            }\n            return;\n        }\n\n        if (!state.hasProperty(BlockStateProperties.OPEN) || state.getValue(BlockStateProperties.OPEN)) return;\n\n        // Ordinary, non-airlock doors retain the room-atmosphere merge behavior.\n        if (event.getLevel() instanceof ServerLevel serverLevel) {\n            RoomEnvironmentManager.equilibrateAcrossClosedDoor(serverLevel, event.getPos());\n            if (event.getEntity() instanceof ServerPlayer player) {\n                RoomEnvironmentManager.invalidate(player);\n            }\n        }\n'''
assert old in text, 'CommonEvents linked-door block missing'
text = text.replace(old, new, 1)
common.write_text(text)

props = ROOT / 'gradle.properties'
p = props.read_text()
assert 'mod_version=0.7.2.2' in p
props.write_text(p.replace('mod_version=0.7.2.2', 'mod_version=0.7.2.3', 1))

afterfall = ROOT / 'src/main/java/dev/afterfall/Afterfall.java'
a = afterfall.read_text()
if 'Afterfall 0.7.2.2 initialized' in a:
    a = a.replace('Afterfall 0.7.2.2 initialized', 'Afterfall 0.7.2.3 initialized', 1)
elif 'Afterfall 0.7.2.1 initialized' in a:
    a = a.replace('Afterfall 0.7.2.1 initialized', 'Afterfall 0.7.2.3 initialized', 1)
elif 'Afterfall 0.7.2 initialized' in a:
    a = a.replace('Afterfall 0.7.2 initialized', 'Afterfall 0.7.2.3 initialized', 1)
afterfall.write_text(a)

print('Afterfall 0.7.2.3 direct linked-door automatic-cycle fix applied')
